import { PROVIDERS } from "../catalog.js";
import type { KitConfig, PhysicalFunction, PlanResult, PlannedWorkflow } from "../types.js";
import { banner, hclObject, q } from "../util/hcl.js";
import { cloudName } from "../util/hash.js";

export interface RenderContext {
  config: KitConfig;
  plan: PlanResult;
  /** Node process.platform of the machine generating the files. */
  platform: NodeJS.Platform;
}

export function fileHeader(config: KitConfig): string {
  return banner([
    "Generated by serverless-kit. Do not edit.",
    "The next `sk package` or `sk deploy` overwrites this directory, except Terraform state.",
    `Service: ${config.service}`,
    `Provider: ${config.provider.name} (${PROVIDERS[config.provider.name].title})`,
    `Stage: ${config.provider.stage}`,
    `Region: ${config.provider.region}`,
    `Terraform provider: ${PROVIDERS[config.provider.name].terraformSource}`,
    `Docs: ${PROVIDERS[config.provider.name].docs}`,
  ]);
}

export function versions(source: string, version: string, extras: Array<{ name: string; source: string; version: string }> = []): string {
  const providers = [
    { name: source.split("/")[1]?.replace("-", "_") ?? "provider", source, version },
    ...extras,
  ];
  // The local name is chosen by the caller via a full block when the default is wrong.
  void providers;
  const blocks = [`    ${blockName(source)} = {\n      source  = ${q(source)}\n      version = ${q(version)}\n    }`];
  for (const extra of extras) {
    blocks.push(`    ${extra.name} = {\n      source  = ${q(extra.source)}\n      version = ${q(extra.version)}\n    }`);
  }
  return `terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n${blocks.join("\n")}\n  }\n}\n`;
}

function blockName(source: string): string {
  if (source.startsWith("hashicorp/")) return source.split("/")[1];
  if (source === "IBM-Cloud/ibm") return "ibm";
  if (source === "aliyun/alicloud") return "alicloud";
  if (source === "oracle/oci") return "oci";
  if (source === "tencentcloudstack/tencentcloud") return "tencentcloud";
  if (source === "huaweicloud/huaweicloud") return "huaweicloud";
  if (source === "cloudflare/cloudflare") return "cloudflare";
  if (source === "digitalocean/digitalocean") return "digitalocean";
  return "provider";
}

export function backendFile(config: KitConfig): string | undefined {
  const backend = config.provider.backend;
  if (!backend || backend.type === "local") return undefined;
  if (backend.type === "s3") {
    const lock = backend.dynamodbTable ? `\n    dynamodb_table = ${q(backend.dynamodbTable)}` : "";
    return `terraform {\n  backend "s3" {\n    bucket = ${q(backend.bucket)}\n    key    = ${q(backend.key)}\n    region = ${q(backend.region)}${lock}\n  }\n}\n`;
  }
  if (backend.type === "gcs") {
    const prefix = backend.prefix ? `\n    prefix = ${q(backend.prefix)}` : "";
    return `terraform {\n  backend "gcs" {\n    bucket = ${q(backend.bucket)}${prefix}\n  }\n}\n`;
  }
  return `terraform {\n  backend "azurerm" {\n    resource_group_name  = ${q(backend.resourceGroup)}\n    storage_account_name = ${q(backend.storageAccount)}\n    container_name       = ${q(backend.container)}\n    key                  = ${q(backend.key)}\n  }\n}\n`;
}

export function functionName(config: KitConfig, fn: PhysicalFunction, max = 63): string {
  return cloudName([config.service, config.provider.stage, fn.physicalName], max);
}

export function envExpressions(config: KitConfig, fn: PhysicalFunction, extra: Record<string, string> = {}): Record<string, string> {
  const entries: Record<string, string> = {};
  for (const [key, value] of Object.entries(fn.environment)) {
    if (key.startsWith("SK_")) continue;
    entries[key] = q(value);
  }
  entries.SK_PROVIDER = q(config.provider.name);
  entries.SK_SERVICE = q(config.service);
  entries.SK_STAGE = q(config.provider.stage);
  entries.SK_REGION = q(config.provider.region);
  entries.SK_FUNCTION_NAME = q(fn.physicalName);
  entries.SK_LOGICAL_NAME = q(fn.logicalName);
  for (const [key, value] of Object.entries(extra)) entries[key] = value;
  return entries;
}

export function tokenExtra(plan: PlanResult): Record<string, string> {
  return plan.needsInvokeToken ? { SK_INVOKE_TOKEN: "random_password.sk_invoke_token.result" } : {};
}

export function randomTokenResource(plan: PlanResult): string {
  if (!plan.needsInvokeToken) return "";
  return `
resource "random_password" "sk_invoke_token" {
  length  = 32
  special = false
}
`;
}

export function randomProvider(): { name: string; source: string; version: string } {
  return { name: "random", source: "hashicorp/random", version: "~> 3.6" };
}

export function envBlock(entries: Record<string, string>, indent = 4): string {
  return hclObject(entries, indent);
}

/** Logical functions that workflows call over HTTP, and the physical function that owns that route. */
export function httpInvokeTargets(plan: PlanResult): PhysicalFunction[] {
  const seen = new Set<string>();
  const out: PhysicalFunction[] = [];
  for (const fn of plan.functions) {
    if (fn.logicalName === "__sk_workflow_runner") continue;
    const internal = fn.events.some((event) => event.type === "http" && event.http.internal);
    if (!internal || seen.has(fn.logicalName)) continue;
    seen.add(fn.logicalName);
    out.push(fn);
  }
  return out;
}

export function runnerFunction(plan: PlanResult): PhysicalFunction | undefined {
  return plan.functions.find((fn) => fn.logicalName === "__sk_workflow_runner");
}

export function urlMapExpression(entries: Array<[string, string]>): string {
  if (entries.length === 0) return q("{}");
  const body = entries.map(([name, expr]) => `      ${q(name)} = ${expr}`).join("\n");
  return `jsonencode({\n${body}\n    })`;
}

export function outputMap(name: string, entries: Record<string, Record<string, string>>): string {
  const items = Object.entries(entries).map(([key, fields]) => {
    const body = Object.entries(fields)
      .map(([field, expr]) => `      ${field} = ${expr}`)
      .join("\n");
    return `    ${q(key)} = {\n${body}\n    }`;
  });
  const value = items.length === 0 ? "{}" : `{\n${items.join("\n")}\n  }`;
  return `output ${q(name)} {\n  value = ${value}\n}\n`;
}

export function workflowOutputs(workflows: PlannedWorkflow[], expr: (workflow: PlannedWorkflow) => Record<string, string>): string {
  const entries: Record<string, Record<string, string>> = {};
  for (const workflow of workflows) entries[workflow.name] = expr(workflow);
  return outputMap("sk_workflows", entries);
}

export function userFunctions(plan: PlanResult): PhysicalFunction[] {
  return plan.functions.filter((fn) => fn.logicalName !== "__sk_workflow_runner");
}
